326:   // ---------- camera ----------
327:   toggleCamera() {
328:     if (this.mode !== "race" && this.mode !== "result") return;
329:     this.cameraMode = this.cameraMode === "cockpit" ? "chase" : "cockpit";
330:     this.audio.ui();
331:   }
332: 
333:   updateCamera(rdt) {
334:     const cam = this.camera;
335:     const px = this.playerGroup.position.x;
336:     const pz = this.playerGroup.position.z;
337:     const t = this.time;
338: 
339:     const inside = this.mode === "race" && this.cameraMode === "cockpit";
340:     if (this.playerModel?.windshieldGroup) this.playerModel.windshieldGroup.visible = !inside;
341:     if (this.playerModel?.windshieldGlass) this.playerModel.windshieldGlass.visible = !inside;
342:     if (this.playerModel?.sideGlassParts) for (const m of this.playerModel.sideGlassParts) m.visible = !inside;
343:     if (this.playerModel?.roofParts) for (const m of this.playerModel.roofParts) m.visible = !inside;
344:     if (this.mode === "menu" || this.mode === "boot" || this.mode === "help") {
345:       const a = 0.68 + Math.sin(t * 0.11) * 0.22;
346:       const r = 8.6;
347:       const target = new THREE.Vector3(px + Math.sin(a) * r, 2.85 + Math.sin(t * 0.19) * 0.12, pz + Math.cos(a) * r);
348:       cam.position.lerp(target, 1 - Math.exp(-rdt * 2.2));
349:       cam.lookAt(px, 0.82, pz + 0.15);
350:       cam.fov += (58 - cam.fov) * Math.min(1, rdt * 2);
351:       cam.updateProjectionMatrix();
352:       return;
353:     }
354: 
355:     if (this.mode === "garage") {
356:       const a = 1.02 + Math.sin(t * 0.1) * 0.1;
357:       const r = 7.6;
358:       const target = new THREE.Vector3(px + Math.sin(a) * r, 2.15, pz + Math.cos(a) * r);
359:       cam.position.lerp(target, 1 - Math.exp(-rdt * 2.4));
360:       cam.lookAt(px, 0.78, pz + 0.1);
361:       cam.fov += (52 - cam.fov) * Math.min(1, rdt * 2);
362:       cam.updateProjectionMatrix();
363:       return;
364:     }
365: 
366:     if (this.mode === "result") {
367:       const a = 0.9 + t * 0.12;
368:       const r = 8.6;
369:       cam.position.lerp(new THREE.Vector3(px + Math.sin(a) * r, 2.6, pz + Math.cos(a) * r), 1 - Math.exp(-rdt * 2));
370:       cam.lookAt(px, 0.9, pz + 0.4);
371:       cam.fov += (52 - cam.fov) * Math.min(1, rdt * 2);
372:       cam.updateProjectionMatrix();
373:       return;
374:     }
375: 
376:     // race
377:     const sim = this.playerSim;
378:     this.playerGroup.updateMatrixWorld(true);
379:     const speedN = Math.min(1, sim.speed / 75);
380:     if (this.cameraMode === "chase") {
381:       const back = 7.4 + speedN * 1.8;
382:       const target = this.playerGroup.localToWorld(new THREE.Vector3(0, 2.55 + speedN * 0.2, -back));
383:       cam.position.lerp(target, 1 - Math.exp(-rdt * 5));
384:       const look = this.playerGroup.localToWorld(new THREE.Vector3(0, 1.0, 1.6));
385:       cam.lookAt(look);
386:       cam.fov += (60 + speedN * 16 - cam.fov) * Math.min(1, rdt * 4);
387:       cam.updateProjectionMatrix();
388:       return;
389:     }
390: 
391:     // cockpit
392:     const accel = sim.accel;
393:     const shake = Math.min(0.02, sim.speed * 0.00007 + sim.wheelspin * 0.01);
394:     const base = this.playerGroup.localToWorld(new THREE.Vector3(-0.37, 1.235, -0.2));
395:     base.x += Math.sin(t * 53) * shake;
396:     base.y += Math.sin(t * 61 + 1.3) * shake * 0.7;
397:     base.z += Math.cos(t * 47) * shake * 0.5;
398:     cam.position.copy(base);
399:     const pitch = -0.055 - accel * 0.0035 + Math.sin(t * 44) * shake * 0.35;
400:     const roll = -this.steer * 0.035 * speedN + Math.sin(t * 37) * shake * 0.3;
401:     const yaw = this.steer * 0.05 * speedN;
402:     cam.rotation.set(pitch, Math.PI + yaw, roll, "YXZ");
403:     const fov = 66 + speedN * 17 + Math.min(4, sim.wheelspin * 4);
404:     cam.fov += (fov - cam.fov) * Math.min(1, rdt * 4);
405:     cam.updateProjectionMatrix();
406:   }
