475:   selectCar(id) {
476:     const save = this.save;
477:     const car = carById(id);
478:     const owned = save.ownedCars.includes(id);
479:     if (!owned) {
480:       if (save.money < car.price) {
481:         this.uiToast(`Faltam ${money(car.price - save.money)} pra levar o ${car.name}.`);
482:         return;
483:       }
484:       save.money -= car.price;
485:       save.ownedCars.push(id);
486:       save.paints[id] = PAINTS[CARS.indexOf(car) % PAINTS.length].id;
487:       if (!save.upgrades[id]) save.upgrades[id] = { engine: 0, tires: 0, weight: 0, gearbox: 0 };
488:       save.selected = id;
489:       persist(save);
490:       this.rebuildPlayerCar();
491:       this.ui.renderGarage(save);
492:       this.uiToast(`${car.name} comprado!`);
493:       this.audio.ui();
494:       return;
495:     }
496:     if (save.selected === id) return;
497:     save.selected = id;
498:     persist(save);
499:     this.rebuildPlayerCar();
500:     this.ui.renderGarage(save);
501:     this.ui.updateMenu(save, this.nextRival());
502:     this.audio.ui();
503:   }
504: 
505:   setPaint(carId, paintId) {
506:     this.save.paints[carId] = paintId;
507:     persist(this.save);
508:     if (carId === this.save.selected && this.playerModel) {
509:       const p = PAINTS.find((x) => x.id === paintId);
510:       if (p) this.playerModel.setPaint(p.hex);
511:     }
512:     this.ui.renderGarage(this.save);
513:     const p = PAINTS.find((x) => x.id === paintId);
514:     this.uiToast(`Pintura: ${p ? p.name : paintId}`);
515:     this.audio.ui();
516:   }
