518:   buyUpgrade(id) {
519:     const save = this.save;
520:     const carId = save.selected;
521:     const upg = UPGRADES.find((u) => u.id === id);
522:     if (!upg) return;
523:     const ups = save.upgrades[carId] || (save.upgrades[carId] = { engine: 0, tires: 0, weight: 0, gearbox: 0 });
