413:     this.renderer.setSize(w, h);
414:     this.renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, this.quality >= 1 ? 1.75 : 1.0));
415:     const portrait = h > w * 1.05 && window.matchMedia("(pointer: coarse)").matches;
416:     document.getElementById("rotate-hint").classList.toggle("hidden", !portrait);
